const events = $input.all()[0].json.body.events || [];
if (events.length === 0) return [];
const event = events[0];
const userMessage = event.message?.text || 'สวัสดี';
const replyToken = event.replyToken;
const userId = event.source?.userId;
return [{ json: { userMessage, replyToken, userId } }];

const compilerRes = $input.all()[0].json;
const replyToken = $('Parse LINE Event').first().json.replyToken;
const textSpoken = compilerRes.compiled_command?.text || 'รับทราบคำสั่งเรียบร้อยแล้วค่ะ';
const face = compilerRes.compiled_command?.face || 'HAPPY';

const flexMessage = {
  type: 'flex',
  altText: '🤖 Zenbo Command Executed',
  contents: {
    type: 'bubble',
    header: {
      type: 'box',
      layout: 'vertical',
      contents: [
        { type: 'text', text: '🤖 Zenbo Robot Active', weight: 'bold', color: '#2563EB', size: 'md' }
      ]
    },
    body: {
      type: 'box',
      layout: 'vertical',
      contents: [
        { type: 'text', text: 'คำสั่งที่รับ: ' + compilerRes.input_text, size: 'sm', weight: 'bold' },
        { type: 'text', text: 'เสียงตอบสนอง: ' + textSpoken, size: 'xs', color: '#475569', margin: 'md' },
        { type: 'text', text: 'สีหน้า: ' + face + ' | สถานะ: กำลังดำเนินการ', size: 'xs', color: '#10B981', margin: 'xs' }
      ]
    }
  }
};

return [{ json: { replyToken, flexMessage } }];
